{
  "probability": 0.87,
  "range_low": 0.75,
  "range_high": 0.95,
  "summary": [
    "- Anchor probability anchored at 0.40 using the Mediterranean fatalities reference class from IOM Missing Migrants Project to frame the baseline.",
    "- February 2026 mortality pace implies March would need a markedly high toll (~294 deaths) to reach 900 by end-March, supporting a high posterior but not a certainty.",
    "- Weather-driven fatality risks (e.g., Cyclone Harry) and underreporting elevate near-term risk, while historical annual toll baselines cap the upside.",
    "- Calibrated posterior yields 87% probability with acknowledged data and correlation uncertainties."
  ],
  "confidence": "medium",
  "narrative": "Starting from a 0.40 anchor in the Missing Migrants reference class, observed early-2026 mortality dynamics—especially weather-driven risks and underreporting—push the probability toward 0.87, though no dedicated forecast confirms 900 by end-March and regulatory or data gaps temper certainty.",
  "justification": {
    "anchor": {
      "probability": 0.40,
      "basis": "Selected from the primary forecast block anchoring on IOM Missing Migrants Project data for Mediterranean fatalities; uses the historical context of ~2,000–2,500 deaths per year to anchor the scale and interpret the 0.40 anchor within a full-year distribution."
    },
    "factor_updates": [
      {
        "factor": "Pace of deaths through February 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "As of late February 2026, about 606 deaths/missing have been recorded, implying March would need to be unusually deadly (~294 deaths) to reach 900 by end-March; a continued high pace raises the probability."
      },
      {
        "factor": "Storm Harry and related severe weather increasing crossing fatalities",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Cyclone Harry and related winter storms in early 2026 are linked to substantial fatalities; weather-driven spikes could push March totals higher."
      },
      {
        "factor": "Funding cuts and reduced search-and-rescue capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Funding cuts and restricted SAR capacity can increase fatalities and undercounting, amplifying near-term death risk."
      },
      {
        "factor": "March would require an unusually high toll to reach 900 by end-March",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "To hit 900 by March end would require ~294 March deaths, which is inconsistent with earlier months' pace; this constrains probability."
      },
      {
        "factor": "Underreporting and ‘invisible’ shipwrecks increasing true toll",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Underreporting implies the true toll could be higher than observed, nudging probability upward."
      },
      {
        "factor": "Historical annual toll baseline (approximately 2,000–2,500 deaths per year)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Even with a volatile start, reaching 900 by end-March would be a large fraction of a typical year, implying a lower probability under normal conditions."
      }
    ],
    "synthesis_rationale": "The anchor provides a baseline context from a reference class with a typical annual toll. Explicit updates pull probability upward where early-2026 signals show elevated mortality and risk (pace, weather, underreporting, SAR constraints) and pull downward where historical annual totals and lack of a dedicated end-March forecast dampen the case for a large early total. Given correlations among factors (e.g., severe weather coinciding with higher death counts) and data uncertainty, the posterior is calibrated to 0.87 with a broad-but-practical uncertainty range."
  }
}

{
  "probability": 0.87,
  "range_low": 0.80,
  "range_high": 0.94,
  "summary": [
    "Posterior probability of at least 900 Mediterranean migrant deaths by end-March 2026 is 0.87, based on a Bayesian update from the February 2026 mortality pace.",
    "Early-2026 data show around 606 deaths/missing by late February, implying March would need a substantial surge to reach 900.",
    "Weather-driven risk (Cyclone Harry and related conditions) and underreporting pressures push the near-term risk upward, while historical annual tolls provide downward pressure.",
    "No formal forecast specifically predicting 900 by end-March is publicly published, so the estimate relies on proximate signals and reporting dynamics."
  ],
  "confidence": "medium",
  "narrative": "Starting from the February mortality pace as the anchor, updates from unusually high early-2026 deaths and weather-driven risk raise the odds of a 900-toll by end-March. The result is a calibrated posterior around 87%, with a wide but plausible uncertainty range given reporting gaps and volatile conditions.",
  "justification": {
    "anchor": {
      "probability": 0.40,
      "basis": "Anchor on the observed early-2026 pace (≈606 deaths/missing by February) against a backdrop of a typical annual toll of 2,000–2,500, making 900 by end-March a substantial but anchorable target."
    },
    "factor_updates": [
      {
        "factor": "Pace of deaths through February 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "As of Feb 2026, about 606 deaths/missing; to reach 900 by end-March would require roughly 294 deaths in March, signaling a potential uptick if the pace persists."
      },
      {
        "factor": "Storm Harry and related severe weather increasing crossing fatalities",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Severe weather events have been linked to elevated fatalities; such shocks can disproportionately lift March mortality if conditions remain unfavorable."
      },
      {
        "factor": "Historical annual toll baseline (approximately 2,000–2,500 deaths per year)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Hitting 900 by end-March would represent a large early share of a typical year's toll, implying the probability is not high under normal conditions."
      },
      {
        "factor": "Policy/regulatory and rescue-operation shifts in Europe",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Stricter policies and changes to rescue capacity could dampen crossings and fatalities, though the net effect is uncertain and context-dependent."
      },
      {
        "factor": "Underreporting and ‘invisible’ shipwrecks increasing true toll",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Persistent concerns about undercounting imply the real toll could be higher than reported, supporting higher risk of hitting 900."
      }
    ],
    "synthesis_rationale": "The 0.87 posterior reflects a Bayesian updating process that weights the high early-2026 mortality signal (upward pushes from pace and weather) against downward anchors from historical annual totals and potential reporting gaps. The raw posterior was capped by correlation and data limitations, yielding a calibrated range of 0.80–0.94 to account for uncertainty and volatile reporting dynamics."
  }
}

{
  "probability": 0.18,
  "range_low": 0.12,
  "range_high": 0.28,
  "summary": [
    "Anchor the forecast around 0.20 based on the reference class; early-2026 data imply a non-negligible risk but hitting 900 by end-March remains unlikely.",
    "Severe weather (Cyclone Harry and related conditions) elevates near-term fatality risk, adding upside pressure to the estimate.",
    "There is no published forecast explicitly predicting 900 deaths by end-March, and the historical annual toll (~2,000–2,500) suggests a large March contribution would be required to reach 900 early in the year.",
    "Policy responses and rescue-capacity constraints could dampen fatalities, offsetting some of the upside from weather and early-year pace."
  ],
  "confidence": "low",
  "narrative": "Starting from a ~20% anchor, the analysis acknowledges a higher-than-average early-2026 death pace and severe weather that could push March fatalities higher, but the lack of a concrete forecast and the need for a large March toll keep the probability below the anchor. Overall, the risk remains non-negligible but uncertain and more likely than not to fall below 0.30."
  ,
  "justification": {
    "anchor": {
      "probability": 0.20,
      "basis": "reference class is Mediterranean migrant fatalities tracked by IOM Missing Migrants Project (Central, Western, Eastern routes). Historically, annual tolls run around 2,000–2,500 deaths per year; February 2026 counts (~606 by late February) imply that reaching 900 by end-March is plausible but not strongly supported by a formal forecast."
    },
    "factor_updates": [
      {
        "factor": "Pace of deaths through February 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "About 606 deaths/missing recorded by late February; to reach 900 by end-March, March would need ~294 deaths, implying a jump from the February pace that is not assured."
      },
      {
        "factor": "Cyclone Harry and related severe weather",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "News reports attribute a sizable share of early-2026 fatalities to severe weather, which would raise March fatalities and push the total toward 900 if conditions persist."
      },
      {
        "factor": "Policy/regulatory changes and SAR capacity",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Tighter policies and changes in rescue operations could dampen crossings and fatalities, offsetting weather-driven risk somewhat."
      },
      {
        "factor": "Underreporting and data gaps",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Known concerns about unreported or hard-to-count incidents suggest the true toll could be higher than reported, supporting upward risk to the forecast."
      }
    ],
    "synthesis_rationale": "Starting from a modest anchor (0.20), the strongest upward pressures come from the high early-year death pace and severe weather; countervailing forces include policy changes and potential undercounting. Given the lack of a formal forecast predicting 900 by end-March, the calibrated probability remains low, with wide uncertainty bounds reflecting data lags, volatility in maritime conditions, and reporting gaps."
  }
}
